  // Decorative large circle (right side)
  slide.addShape(pres.shapes.OVAL, { x: 6.8, y: -1.0, w: 4.5, h: 4.5, fill: { color: C.iceBlue, transparency: 82 }, line: { color: C.iceBlue, transparency: 82 } });
  slide.addShape(pres.shapes.OVAL, { x: 7.5, y: 0.2, w: 3.0, h: 3.0, fill: { color: C.iceBlue, transparency: 75 }, line: { color: C.iceBlue, transparency: 75 } });

  // "ACT TWO" eyebrow
  slide.addText("ACT TWO", {
    x: 0.5, y: 1.3, w: 7, h: 0.4,
    fontFace: FONT_BODY, fontSize: 11, color: C.accent, bold: true, align: "left",
    charSpacing: 5, margin: 0
  });

  // Main title
  slide.addText("Generative AI's Act Two:", {
    x: 0.5, y: 1.75, w: 8.5, h: 0.75,
    fontFace: FONT_TITLE, fontSize: 40, color: C.white, bold: true, align: "left", margin: 0
  });
  slide.addText("From Technology Hammer to Real Value", {
    x: 0.5, y: 2.5, w: 8.5, h: 0.65,
    fontFace: FONT_TITLE, fontSize: 32, color: C.iceBlue, bold: false, align: "left", margin: 0
