  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.3, w: 4.5, h: 0.04, fill: { color: C.accent }, line: { color: C.accent } });

  // Attribution
  slide.addText("Sonya Huang, Pat Grady & GPT-4  ·  Sequoia Capital  ·  September 2023", {
    x: 0.5, y: 3.55, w: 8.5, h: 0.35,
    fontFace: FONT_BODY, fontSize: 12, color: C.iceBlue, align: "left", margin: 0
  });

  // Footer
  slide.addText("SEQUOIA CAPITAL — CONFIDENTIAL", {
    x: 0.5, y: 5.22, w: 9, h: 0.25,
    fontFace: FONT_BODY, fontSize: 9, color: C.midGray, align: "left", margin: 0
  });
  slide.addText("1", { x: 9.5, y: 5.22, w: 0.3, h: 0.25, fontFace: FONT_BODY, fontSize: 9, color: C.midGray, align: "right", margin: 0 });
